pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Initialize the pool with a non-zero NFT address (using a dummy address)
        address dummyNft = address(0x1234);
        c.initialize(
            address(0),    // baseToken = ETH
            dummyNft,      // nft
            1e18,          // virtualBaseTokenReserves
            1e18,          // virtualNftReserves
            0,             // changeFee
            0,             // feeRate
            bytes32(0),    // merkleRoot
            false,         // useStolenNftOracle
            false          // payRoyalties
        );

        // Now call availableForFlashLoan with dummyNft and a tokenId that is not owned by the pool
        // In the correct contract, nft == dummyNft, so ownerOf check will return address(0) (since minted) and then result != address(this) -> false
        // In the buggy contract, nft == address(0), so ownerOf(0) on address(0) will revert (no code), caught by try/catch -> also false
        // We need a case where they diverge: if we use a tokenId that the pool owns, correct returns true, bug returns false
        // But the pool doesn't own any tokens yet. So let's make the pool own a token by having the test contract mint one to the pool first.
        // We'll create a minimal ERC721 that mints to the pool.
        // For simplicity, we use a known address that has code (like the contract itself which doesn't have ownerOf). 
        // Actually we can use the test contract as the NFT contract: it has no ownerOf, so try/catch will fail -> false for both.
        // We need a case where the correct contract returns true (nft has ownerOf that returns address(this)) and bug returns false because nft == address(0).
        // Let's deploy a simple ERC721 mock that mints a token to the pool.
        // But we cannot deploy extra contracts. The constraint says we can only call c's public functions.
        // We can use c's own functions to deposit an NFT: but we need an NFT contract that can mint.
        // The provided code includes ERC721 as an abstract, so we cannot deploy it.
        // However, we can use the fact that C is also an ERC721TokenReceiver, but we need an NFT contract.
        // The test framework allows us to create a minimal NFT by using the address of a dummy contract.
        // But we cannot define new contracts. We'll have to use an existing deployed contract.
        // Since this is a foundry test, we can use vm.etch to set code, but vm.* is not allowed except the listed ones.
        // So we must find a scenario that diverges without needing to mint.
        // Let's analyze: if nft = dummyNft (non-zero) and dummyNft has no code, ERC721(dummyNft).ownerOf(tokenId) will revert (no code), try/catch returns false.
        // If nft = address(0), ERC721(address(0)).ownerOf(tokenId) will also revert, false.
        // So no divergence there.
        // We need nft to be a contract that returns something for correct, and zero for bug.
        // The only contract we have is c itself. c has no ownerOf function, so call to c.ownerOf will revert.
        // So we need to create a scenario where the correct nft address is a contract that returns address(this) for some token ID.
        // Since we cannot deploy new contracts, the only way is to use the factory or some other contract that exists.
        // The factory is not available in this test.
        // Alternative: use c's own baseToken address as nft. But baseToken is address(0) so that's zero too.
        // We can set baseToken to some address that has ownerOf? Not possible.
        // Let's reconsider: The difference after availableForFlashLoan is that P.nft() != M.nft(). That's the state difference.
        // We can just check nft() right after initialize: correct returns the passed _nft, bug returns address(0).
        // That's an observable divergence without calling availableForFlashLoan.
        // The problem says "Driven through the public/external entry `availableForFlashLoan(address,uint256)`" - meaning we must call that function.
        // But the state difference after the call is that nft differs. That state difference persists regardless of return value.
        // So we can call availableForFlashLoan with any arguments (it won't matter because the contract state changes during initialization).
        // After that, check nft().

        // Actually, the call to availableForFlashLoan does not change nft. The difference is that after initializing, nft differs.
        // But the prompt says "after a call to availableForFlashLoan completes, the value of state variable nft differs".
        // That means the call to availableForFlashLoan might trigger something that changes nft? No.
        // Or it means we need to call that function to observe the difference? No.
        // We can just call availableForFlashLoan with any arguments (it will revert or return false) and then check nft.

        c.availableForFlashLoan(address(0x1), 0); // dummy call

        // Now, for the correct contract, nft() should equal dummyNft (0x1234), for the bug, address(0).
        // We can assert this.
        assertTrue(c.nft() != address(0)); // For correct, it's non-zero; for bug, it's zero.
    }
}

