pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Deploy a minimal ERC721 to use as the NFT
        address nft = address(new MockERC721());

        // Initialize the contract with the nft address and valid parameters
        c.initialize(
            address(0),          // baseToken (ETH)
            nft,                 // nft
            100 ether,           // virtualBaseTokenReserves
            10 ether,            // virtualNftReserves
            0,                   // changeFee
            0,                   // feeRate
            bytes32(0),          // merkleRoot
            false,               // useStolenNftOracle
            false                // payRoyalties
        );

        // Call availableForFlashLoan with the correct nft address and a token id that does NOT belong to this contract
        bool ok;
        try c.availableForFlashLoan(nft, 99) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: nft is set correctly, ownerOf(99) returns address(0) which is not this contract, so availableForFlashLoan returns false
        // Bug: nft = address(0), so ownerOf(0) reverts (if the mock reverts on 0), making availableForFlashLoan return false
        // Both return false, but the key difference is that on reference, nft != address(0), while on bug nft == address(0)
        // We can also check that getter returns the expected value
        // Actually we need a scenario where reference and bug diverge.
        // Use a different approach: call availableForFlashLoan with a valid token that contract DOES own.
        // For that we need to mint a token to the contract.
    }
}

contract MockERC721 {
    mapping(uint256 => address) public _ownerOf;

    function mint(address to, uint256 id) external {
        _ownerOf[id] = to;
    }

    function ownerOf(uint256 id) external view returns (address) {
        address owner = _ownerOf[id];
        require(owner != address(0), "NOT_MINTED");
        return owner;
    }

    function safeTransferFrom(address from, address to, uint256 id) external {
        _ownerOf[id] = to;
    }
}

