import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testRegression_property() public {
        // Call availableForFlashLoan to trigger the bug (in the buggy version, this call
        // will execute the no-op require(true) and thus the feeRate will be updated incorrectly)
        // The reference version will also call availableForFlashLoan but won't change feeRate.
        // We'll first initialize the pool with a feeRate > 5000 to see the difference.

        // Deployer calls initialize directly (since we own the factory proxy)
        vm.prank(address(this));
        // This call will revert in the reference (feeRate > 5000) but succeed in the buggy version
        c.initialize(address(0), address(this), 1000e18, 1000e18, 100, 6000, bytes32(0), false, false);

        // After initialization (which fails in reference), check if feeRate changed
        // In reference, the revert prevents feeRate from being set
        // In buggy, feeRate becomes 6000

        // availableForFlashLoan will not revert, but it will execute the buggy setFeeRate logic
        // Actually, the bug is in setFeeRate, not availableForFlashLoan.
        // Let's directly call setFeeRate via the onlyOwner path.

        // Reset: deploy a fresh contract
        c = new C(address(this), address(this), address(this));

        // Initialize with valid parameters
        c.initialize(address(0), address(this), 1000e18, 1000e18, 100, 100, bytes32(0), false, false);

        // Now call setFeeRate with a value > 5000
        // In reference: reverts, feeRate stays 100
        // In buggy: succeeds, feeRate becomes 6000

        uint16 initialFeeRate = c.feeRate();

        // Try to set feeRate above 5000
        try c.setFeeRate(6000) {
            // If no revert (buggy version), check that feeRate changed incorrectly
            assertTrue(c.feeRate() != initialFeeRate, "Bug: feeRate should not have changed");
        } catch {
            // If revert (reference version), feeRate should remain unchanged
            assertTrue(c.feeRate() == initialFeeRate, "Reference: feeRate should stay the same");
        }
    }
}

